const crypto = require('crypto');
const headers = $input.item.json.headers || {};

// --- HMAC-SHA256 Signature Verification over the RAW request bytes ---
// GitHub signs the original bytes; JSON parse+stringify can change escaping
// and whitespace, so the Webhook node runs with options.rawBody=true and we
// hash the exact bytes it captured (binary property `data`).
const bin = $input.item.binary && $input.item.binary.data;
if (!bin || !bin.data) {
  throw new Error('Raw request body missing - Webhook rawBody option must be enabled');
}
const rawBody = Buffer.from(bin.data, 'base64');

const webhookSecret = $env.GH_WEBHOOK_SECRET;
const signatureHeader = headers['x-hub-signature-256'] || '';

if (!webhookSecret) {
  throw new Error('GH_WEBHOOK_SECRET not configured in n8n environment');
}

if (!signatureHeader) {
  throw new Error('Missing x-hub-signature-256 header - rejecting unsigned webhook');
}

const expectedSig = 'sha256=' + crypto.createHmac('sha256', webhookSecret).update(rawBody).digest('hex');
const sigBuffer = Buffer.from(signatureHeader);
const expectedBuffer = Buffer.from(expectedSig);

if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
  throw new Error('Invalid webhook signature - HMAC verification failed');
}

// Signature verified - parse event from the same raw bytes we verified
const body = JSON.parse(rawBody.toString('utf8'));
const eventType = headers['x-github-event'] || body.event || 'unknown';
const deliveryId = headers['x-github-delivery'] || 'no-delivery-id';

return {
  json: {
    event_type: eventType,
    delivery_id: deliveryId,
    original_body: body,
    timestamp: new Date().toISOString(),
    signature_verified: true,
    headers: {
      'x-github-event': eventType,
      'x-github-delivery': deliveryId
    }
  }
};

