const event = $json;
const body = event.original_body || {};
const repo = body.repository || {};
const workflowRun = body.workflow_job || body.workflow_run || {};
const action = body.action || 'queued';

// Determine runner name from labels if available
const runnerName = (workflowRun.labels || []).find(l => 
  l.startsWith('self-hosted') && !l.includes('self-hosted-only')
)?.replace('self-hosted-', '') || 'unknown';

// Create NATS event envelope (PMOVES standard)
const natsEvent = {
  id: $node.id,
  topic: `github.job.${action}.v1`,
  ts: event.timestamp,
  version: 'v1',
  source: 'github-webhook',
  payload: {
    repository: repo.full_name || repo.name || 'unknown',
    workflow: workflowRun.name || body.workflow || 'unknown',
    runner: runnerName,
    job_id: workflowRun.id || body.workflow_job?.id || body.id,
    status: workflowRun.status || action,
    started_at: workflowRun.started_at || workflowRun.run_started_at,
    completed_at: workflowRun.completed_at,
    conclusion: workflowRun.conclusion,
    actor: body.sender?.login || body.sender?.name || 'unknown',
    event_id: event.delivery_id
  },
  correlation_id: event.delivery_id,
  parent_id: null
};

return {
  json: {
    nats_subject: natsEvent.topic,
    nats_payload: natsEvent,
    github_event: event.event_type
  }
};

const payload = $node['Create NATS Event Envelope'].json.nats_payload;
const status = payload.payload?.status || 'unknown';
const conclusion = payload.payload?.conclusion || 'pending';
const repo = payload.payload?.repository || 'unknown';
const workflow = payload.payload?.workflow || 'unknown';
const runner = payload.payload?.runner || 'unknown';

const discordUrl = $env.DISCORD_WEBHOOK_URL;
if (!discordUrl) {
  throw new Error('DISCORD_WEBHOOK_URL not configured in n8n environment');
}

let emoji = '⏳';
if (status === 'in_progress') emoji = '🔄';
else if (status === 'completed') {
  emoji = conclusion === 'success' ? '✅' : conclusion === 'failure' ? '❌' : '⚠️';
}

const embed = {
  title: `${emoji} GitHub Job ${status}`,
  description: `**${workflow}** in ${repo}`,
  color: conclusion === 'success' ? 0x00FF00 : conclusion === 'failure' ? 0xFF0000 : 0xFFFF00,
  fields: [
    {
      name: 'Repository',
      value: repo,
      inline: true
    },
    {
      name: 'Runner',
      value: runner,
      inline: true
    },
    {
      name: 'Status',
      value: status,
      inline: true
    },
    {
      name: 'Conclusion',
      value: conclusion || 'pending',
      inline: true
    },
    {
      name: 'Job ID',
      value: payload.payload?.job_id || 'unknown',
      inline: false
    },
    {
      name: 'Actor',
      value: payload.payload?.actor || 'unknown',
      inline: true
    },
    {
      name: 'Timestamp',
      value: payload.ts || new Date().toISOString(),
      inline: false
    }
  ]
};

return {
  json: {
    webhookUrl: discordUrl,
    payload: {
      username: 'PMOVES GitHub Runner Monitor',
      embeds: [embed]
    }
  }
};

const event = $json;
return {
  json: {
    message: `Ignored GitHub event type: ${event.event_type}`,
    event_type: event.event_type,
    delivery_id: event.delivery_id
  }
};

const errorNode = $input.item.json.$error?.node?.name || 'unknown';
const errorMessage = $input.item.json.$error?.message || $input.item.json.error?.message || 'No error message';
const timestamp = new Date().toISOString();
console.error(`[github_webhook] Error in ${errorNode}: ${errorMessage} at ${timestamp}`);
return { json: { error: true, node: errorNode, message: errorMessage, timestamp } };
